function strip(s) {
  return (s||"").replace(/<[^>]*>/g," ").replace(/<!\[CDATA\[|\]\]>/g,"").replace(/&[^;]+;/g," ").replace(/\s+/g," ").trim();
}

function parseRSS(xml) {
  const out = [];
  let re = /<item>([\s\S]*?)<\/item>/gi;
  let m;
  while ((m = re.exec(xml)) !== null) {
    const it = m[1];
    const t = (it.match(/<title>([\s\S]*?)<\/title>/i) || [])[1] || "";
    const l = (it.match(/<link>([\s\S]*?)<\/link>/i) || [])[1] || "";
    const d = (it.match(/<description>([\s\S]*?)<\/description>/i) || [])[1] || "";
    const c = (it.match(/<content:encoded>([\s\S]*?)<\/content:encoded>/i) || [])[1] || d;
    const p = (it.match(/<pubDate>([\s\S]*?)<\/pubDate>/i) || [])[1] || "";
    const s = (it.match(/<source[^>]*>([\s\S]*?)<\/source>/i) || [])[1] || "";
    const img = (it.match(/<enclosure[^>]*url="([^"]+)"[^>]*type="image\/[^"]+"/i) || [])[1] ||
               (it.match(/<media:content[^>]*url="([^"]+)"[^>]*medium="image"/i) || [])[1] ||
               (it.match(/<media:content[^>]*url="([^"]+)"[^>]*type="image\/[^"]+"/i) || [])[1] || "";
    if (t && l) {
      out.push({
        title: strip(t),
        link: strip(l),
        desc: strip(d),
        contentEncoded: strip(c),
        pubDate: strip(p),
        source: strip(s),
        image: img
      });
    }
  }
  re = /<entry>([\s\S]*?)<\/entry>/gi;
  while ((m = re.exec(xml)) !== null) {
    const it = m[1];
    const t = (it.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || "";
    const l = (it.match(/<link[^>]*href="([^"]+)"/i) || [])[1] || "";
    const s = (it.match(/<summary[^>]*>([\s\S]*?)<\/summary>/i) || [])[1] || "";
    const u = (it.match(/<updated>([\s\S]*?)<\/updated>/i) || [])[1] || (it.match(/<published>([\s\S]*?)<\/published>/i) || [])[1] || "";
    if (t && l) {
      out.push({
        title: strip(t),
        link: l.trim(),
        desc: strip(s),
        pubDate: strip(u),
        source: "",
        image: ""
      });
    }
  }
  return out;
}

function isFresh(pubDate, maxHours) {
  if (!pubDate) return false;
  const d = new Date(pubDate);
  if (isNaN(d.getTime())) return false;
  return (Date.now() - d.getTime()) / 3600000 <= maxHours;
}

function isTech(title, desc) {
  const txt = ((title||"") + " " + (desc||"")).toLowerCase();
  for (const kw of REJ_KW) { if (txt.includes(kw)) return false; }
  for (const kw of TECH_KW) { if (txt.includes(kw)) return true; }
  return false;
}

function makeId() {
  return "art-" + Date.now() + "-" + Math.random().toString(36).slice(2,8);
}

function contentHash(title, desc) {
  function norm(s) { return (s||"").replace(/[\u0623\u0625\u0622]/g,"\u0627").replace(/\u0629/g,"\u0647").replace(/[\u0649\u064A]/g,"\u064A").replace(/\s+/g," ").trim().toLowerCase(); }
  const hi = norm(title) + "|" + norm(desc||"").substring(0,100);
  let h = 0;
  const t = hi.replace(/[^\w\u0600-\u06FF]/g,"");
  for (let i = 0; i < t.length; i++) { h = ((h << 5) - h) + t.charCodeAt(i); h |= 0; }
  return Math.abs(h).toString(36);
}

async function ghGet(path) {
  try {
    return await this.helpers.httpRequest({
      method: "GET",
      url: GH_API + "/" + path,
      headers: GH_H
    });
  } catch(e) {
    return {};
  }
}

async function ghPut(path, content, msg) {
  try {
    const existing = await ghGet(path);
    return await this.helpers.httpRequest({
      method: "PUT",
      url: GH_API + "/" + path,
      headers: GH_H,
      body: {
        message: msg || "TDN Lite v2",
        content: Buffer.from(content).toString("base64"),
        sha: existing.sha || ""
      }
    });
  } catch(e) {
    throw new Error("GitHub PUT " + path + ": " + e.message);
  }
}

function b64decode(encoded) {
  return JSON.parse(Buffer.from(encoded, "base64").toString());
}

async function aiTranslate(title, desc, source) {
  const userPrompt = `اكتب مقالاً إخبارياً بالعربية عن الخبر التالي:\n\nالعنوان الأصلي: ${title}\nالوصف: ${desc}\nالمصدر: ${source}\n\nالمطلوب بصيغة JSON فقط:\n{\n  "title_ar": "عنوان جذاب بالعربية (أقل من 65 حرف)"\n  "seo_title": "عنوان محسن لمحركات البحث (50-60 حرف)"\n  "meta_description": "وصف مختصر لمحركات البحث (150-160 حرف)"\n  "seo_slug": "slug-مناسب-للمقال"\n  "excerpt": "ملخص مشوق من 2-3 جمل (أقل من 160 حرف)"\n  "body": "المقال الكامل (300-500 كلمة) - كل فقرة بسطر منفصل بدون HTML"\n  "telegram_summary": "نسخة مختصرة من 3-4 جمل للتليجرام"\n  "category": "ai | cybersecurity | companies | phones | ev"\n  "tags": ["تاغ ذو صلة", "تاغ ثاني", "تاغ ثالث"]\n  "focus_keyword": "الكلمة المفتاحية الأساسية"\n  "secondary_keywords": ["كلمة مفتاحية ثانوية"]\n  "long_tail_keywords": ["عبارة بحث طويلة"]\n  "primary_company": "الشركة الأساسية أو null"\n  "secondary_company": "شركة أخرى أو null"\n  "products": ["منتج مذكور"] أو []\n  "devices": ["جهاز مذكور"] أو []\n  "technologies": ["تقنية مذكورة"] أو []\n  "ai_models": ["نموذج ذكاء اصطناعي"] أو []\n  "countries": ["دولة"] أو []\n  "people": ["شخصية"] أو []\n  "stocks": ["رمز سهم"] أو []\n  "image_queries": ["كلمة بحث رئيسية للصورة", "كلمة بديلة", "كلمة تقنية عامة"]\n}`;
  const res = await this.helpers.httpRequest({
    method: "POST",
    url: "https://api.groq.com/openai/v1/chat/completions",
    headers: { "Authorization": "Bearer " + GROQ_API_KEY, "Content-Type": "application/json" },
    body: {
      model: GROQ_MODEL,
      messages: [
        { role: "system", content: AI_SYSTEM_PROMPT },
        { role: "user", content: userPrompt }
      ],
      temperature: 0.2,
      max_tokens: 1200,
      response_format: { type: "json_object" }
    }
  });
  return JSON.parse(res.choices[0].message.content);
}

async function main() {
  const result = {
    status: "ok",
    rss_items: 0,
    after_freshness: 0,
    after_tech_filter: 0,
    after_dedup: 0,
    ai_success: false,
    article_id: null,
    article_url: null,
    telegram_sent: false
  };

  // ===== RSS COLLECTION =====
  // Step 1: Fetch all RSS sources concurrently (tier 1 first, then tier 2)
  let allItems = [];

  // Helper to fetch and parse a single RSS source
  async function fetchSource(src) {
    try {
      const res = await this.helpers.httpRequest({ method: "GET", url: src.url });
      const xml = typeof res === "string" ? res : (res.data || res.body || "");
      if (!xml || xml.length < 100) return [];
      const items = parseRSS(xml);
      items.forEach(i => { i._source = src.name; i._lang = src.lang; i._tier = src.tier; });
      return items;
    } catch(e) {
      return [];
    }
  }

  const tier1 = RSS_SOURCES.filter(s => s.tier === 1);
  const tier2 = RSS_SOURCES.filter(s => s.tier === 2);

  // Fetch tier 1 first (faster response expected), then tier 2
  let tier1Results = await Promise.allSettled(tier1.map(fetchSource));
  let tier2Results = await Promise.allSettled(tier2.map(fetchSource));

  for (const r of tier1Results) { if (r.status === "fulfilled") allItems.push(...r.value); }
  for (const r of tier2Results) { if (r.status === "fulfilled") allItems.push(...r.value); }

  // Step 1b: Fall back to Google News if no items from primary sources
  if (allItems.length === 0) {
    try {
      const res = await this.helpers.httpRequest({ method: "GET", url: GNEWS_FALLBACK });
      const xml = typeof res === "string" ? res : (res.data || res.body || "");
      if (xml && xml.length >= 100) {
        const gnItems = parseRSS(xml);
        gnItems.forEach(i => { i._source = "Google News"; i._lang = "en"; i._tier = 3; });
        allItems.push(...gnItems);
      }
    } catch(e) {}
  }

  if (allItems.length === 0) {
    result.status = "empty_rss";
    return result;
  }

  // Deduplicate by link across all sources
  const seenLinks = new Set();
  const deduped = [];
  for (const item of allItems) {
    if (!seenLinks.has(item.link)) {
      seenLinks.add(item.link);
      deduped.push(item);
    }
  }

  result.rss_items = deduped.length;

  // Step 2: Sort by source tier (1=best), then freshness
  deduped.sort((a, b) => {
    if (a._tier !== b._tier) return a._tier - b._tier;
    const da = a.pubDate ? new Date(a.pubDate).getTime() : 0;
    const db = b.pubDate ? new Date(b.pubDate).getTime() : 0;
    return db - da;
  });

  // Step 3: Freshness filter (24 hours for testing)
  const fresh = deduped.filter(i => isFresh(i.pubDate, 24));
  result.after_freshness = fresh.length;
  if (fresh.length === 0) {
    result.status = "all_stale";
    return result;
  }

  // Step 4: Tech filter
  const tech = fresh.filter(i => isTech(i.title, i.desc));
  result.after_tech_filter = tech.length;
  if (tech.length === 0) {
    result.status = "no_tech";
    return result;
  }

  // Step 5: Duplicate check
  let existingHashes = [];
  try {
    const hr = await ghGet("data/content_hashes.json");
    if (hr.content) existingHashes = b64decode(hr.content);
  } catch(e) {}

  const newItems = [];
  for (const item of tech) {
    const h = contentHash(item.title, item.contentEncoded || item.desc);
    if (!existingHashes.includes(h)) {
      newItems.push({ item, hash: h });
    }
  }
  result.after_dedup = newItems.length;
  if (newItems.length === 0) {
    result.status = "all_duplicates";
    return result;
  }

  // ===== AI TRANSLATION =====
  // Step 6: Take first new item
  const { item: picked, hash } = newItems[0];
  const articleId = makeId();
  const sourceName = picked._source || picked.source || "Google News";
  const techdoseLink = FRONTEND_URL + "/article.html?id=" + articleId;
  const imageUrl = picked.image || "https://images.unsplash.com/photo-1518770660439-4636190af475?w=800&q=80";

  // Step 7: AI translation (single call)
  let ai;
  try {
    ai = await aiTranslate(picked.title, picked.contentEncoded || picked.desc, sourceName);
    result.ai_success = true;
  } catch(e) {
    result.status = "ai_failed";
    result.ai_error = e.message;
    return result;
  }

  const aiTitle = ai.title_ar || picked.title;
  const aiExcerpt = (ai.excerpt || ai.body || "").substring(0, 300);
  const aiBody = ai.body || "";
  const aiTg = ai.telegram_summary || ai.excerpt || "";
  const aiCategory = ai.category || "\u062A\u0643\u0646\u0648\u0644\u0648\u062C\u064A\u0627";
  const aiTags = Array.isArray(ai.tags) ? ai.tags : ["\u062A\u0643\u0646\u0648\u0644\u0648\u062C\u064A\u0627"];


  // SEO metadata
  const seoTitle = ai.seo_title || aiTitle;
  const metaDesc = ai.meta_description || aiExcerpt.substring(0, 160);
  const seoSlug = ai.seo_slug || "";
  const focusKw = ai.focus_keyword || "";
  const secondaryKws = Array.isArray(ai.secondary_keywords) ? ai.secondary_keywords : [];
  const longTailKws = Array.isArray(ai.long_tail_keywords) ? ai.long_tail_keywords : [];

  // Entity extraction
  const primaryCompany = ai.primary_company || null;
  const secondaryCompany = ai.secondary_company || null;
  const products = Array.isArray(ai.products) ? ai.products : [];
  const devices = Array.isArray(ai.devices) ? ai.devices : [];
  const technologies = Array.isArray(ai.technologies) ? ai.technologies : [];
  const aiModels = Array.isArray(ai.ai_models) ? ai.ai_models : [];
  const countries = Array.isArray(ai.countries) ? ai.countries : [];
  const people = Array.isArray(ai.people) ? ai.people : [];
  const stocks = Array.isArray(ai.stocks) ? ai.stocks : [];
  const imageQueries = Array.isArray(ai.image_queries) ? ai.image_queries : [];

  const bodyHtml = "<p>" + aiBody.replace(/\n\n/g, "</p><p>").replace(/\n/g, "<br>") + "</p>";

  const article = {
    id: articleId,
    title_ar: aiTitle,
    excerpt: aiExcerpt,
    body: bodyHtml,
    category: aiCategory,
    tags: aiTags,
    image: imageUrl,
    source_link: picked.link,
    source_name: sourceName,
    status: "published",
    readTime: Math.ceil(aiBody.split(/\s+/).length / 200) + " min read",
    created_at: new Date().toISOString()};

  // ===== PUBLISHING =====
  // Step 8: Update index (single source of truth)
  let index = [];
  try {
    const ir = await ghGet("data/articles/index.json");
    if (ir.content) index = b64decode(ir.content);
  } catch(e) {}
  index.unshift({
    id: article.id,
    title: article.title_ar,
    excerpt: article.excerpt,
    body: article.body,
    category: article.category,
    tags: article.tags,
    image: article.image,
    date: article.created_at,
    readTime: article.readTime,
    views: "0",
    hasEgyptImpact: false,
    source: article.source_name,
    link: article.source_link,
    techdose_link: techdoseLink,
    status: "published",
    // SEO metadata
    seo_title: seoTitle,
    meta_description: metaDesc,
    seo_slug: seoSlug,
    focus_keyword: focusKw,
    secondary_keywords: secondaryKws,
    long_tail_keywords: longTailKws,
    // Entity extraction
    primary_company: primaryCompany,
    secondary_company: secondaryCompany,
    products: products,
    devices: devices,
    technologies: technologies,
    ai_models: aiModels,
    countries: countries,
    people: people,
    stocks: stocks,
    // Image queries
    image_queries: imageQueries
  });
  if (index.length > 500) index.length = 500;
  await ghPut("data/articles/index.json", JSON.stringify(index, null, 2), "Index: " + aiTitle.substring(0,80));

  // Step 9: Update content hashes
  existingHashes.unshift(hash);
  if (existingHashes.length > 10000) existingHashes.length = 10000;
  await ghPut("data/content_hashes.json", JSON.stringify(existingHashes, null, 2), "Hash: " + aiTitle.substring(0,80));

  // Step 10: Update published links
  try {
    const lr = await ghGet("data/published_links.json");
    let links = lr.content ? b64decode(lr.content) : [];
    links.unshift(picked.link);
    if (links.length > 5000) links.length = 5000;
    await ghPut("data/published_links.json", JSON.stringify(links, null, 2), "Link: " + aiTitle.substring(0,80));
  } catch(e) {}

  // Step 11: Update published topics
  try {
    const tr = await ghGet("data/published_topics.json");
    let topics = tr.content ? b64decode(tr.content) : [];
    topics.unshift({ title: aiTitle, source: sourceName, timestamp: article.created_at, topic_fp: "" });
    if (topics.length > 500) topics.length = 500;
    await ghPut("data/published_topics.json", JSON.stringify(topics, null, 2), "Topic: " + aiTitle.substring(0,80));
  } catch(e) {}

  result.article_id = articleId;
  result.article_url = techdoseLink;

  // ===== TELEGRAM NOTIFICATION =====
  // Step 12: Send Telegram
  try {
    const htmlMsg = "\uD83D\uDCF0 <b>" + aiTitle + "</b>\n\n"
      + aiTg + "\n\n"
      + "\uD83D\uDD17 <a href=\"" + techdoseLink + "\">\u0627\u0642\u0631\u0623 \u0627\u0644\u062E\u0628\u0631 \u0643\u0627\u0645\u0644\u0627\u064B</a>\n"
      + "\uD83D\uDCC4 \u0627\u0644\u0645\u0635\u062F\u0631: " + sourceName;

    const tgRes = await this.helpers.httpRequest({
      method: "POST",
      url: "https://api.telegram.org/bot" + TG_TOKEN + "/sendMessage",
      headers: { "Content-Type": "application/json" },
      body: {
        chat_id: TG_CHAT_ID,
        text: htmlMsg,
        parse_mode: "HTML",
        disable_web_page_preview: false
      }
    });

    result.telegram_sent = true;
    result.telegram_message_id = tgRes.result ? tgRes.result.message_id : null;
    result.status = "published";
  } catch(e) {
    result.telegram_error = e.message;
    result.status = "published_tg_failed";
  }

  return result;
}

const _r = await main();
return [{ json: _r }];

